USE blue_fit;
CREATE TABLE IF NOT EXISTS members (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, branch_id CHAR(36) NOT NULL, member_code VARCHAR(24) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, document_number VARCHAR(30), phone VARCHAR(25), email VARCHAR(190), status ENUM('active','inactive','blocked') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, UNIQUE KEY uq_member_code(organization_id,member_code), UNIQUE KEY uq_member_doc(organization_id,document_number), FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE IF NOT EXISTS plans (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, name VARCHAR(120) NOT NULL, price DECIMAL(10,2) NOT NULL, duration_months SMALLINT UNSIGNED NOT NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS memberships (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, branch_id CHAR(36) NOT NULL, member_id CHAR(36) NOT NULL, plan_id CHAR(36) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, price DECIMAL(10,2) NOT NULL, balance DECIMAL(10,2) NOT NULL, status ENUM('pending','active','expired','suspended','cancelled') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(member_id) REFERENCES members(id), FOREIGN KEY(plan_id) REFERENCES plans(id));
CREATE TABLE IF NOT EXISTS payment_records (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, membership_id CHAR(36) NOT NULL, member_id CHAR(36) NOT NULL, amount DECIMAL(10,2) NOT NULL, method ENUM('cash','yape','plin','card','transfer','credit','mixed') NOT NULL, operation_number VARCHAR(80), paid_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, received_by CHAR(36) NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(membership_id) REFERENCES memberships(id), FOREIGN KEY(member_id) REFERENCES members(id));
CREATE TABLE IF NOT EXISTS checkins (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, branch_id CHAR(36) NOT NULL, member_id CHAR(36) NOT NULL, membership_id CHAR(36), method ENUM('dni','member_code','qr','manual') NOT NULL, result ENUM('allowed','denied') NOT NULL, reason VARCHAR(255), checkin_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(member_id) REFERENCES members(id));
INSERT INTO plans(id,organization_id,name,price,duration_months) SELECT UUID(),'00000000-0000-4000-8000-000000000001','Mensual Full',99.90,1 WHERE NOT EXISTS(SELECT 1 FROM plans WHERE name='Mensual Full');
